func Profiles() []Profile {
	var profiles []Profile
	if err := json.Unmarshal([]byte(catalogJSON), &profiles); err != nil {
		panic("decode generated performance fixture profile catalog: " + err.Error())
	}
	return profiles
}

func Lookup(profileID string) (Profile, bool) {
	for _, profile := range Profiles() {
		if profile.FixtureProfileID == profileID {
			return profile, true
		}
	}
	return Profile{}, false
}
